double calculate_wigner_weight(size_t n, double r, size_t k) {
    using namespace boost::math;

    // Calculate (-1)^n / π
    double sign_factor = (n % 2 == 0) ? 1.0 : -1.0;
    sign_factor /= boost::math::constants::pi<double>();

    // Calculate sqrt(n!/(n+k)!)
    double factorial_ratio = 1.0;
    if (k == 0) {
        factorial_ratio = 1.0;
    } else {
        factorial_ratio = sqrt(factorial<double>(n) / factorial<double>(n + k));
    }

    // Calculate exp(-2*r^2)
    double exp_factor = exp(-2.0 * r * r);

    // Calculate (2*r)^k
    double r_factor = pow(2.0 * r, static_cast<double>(k));

    // Calculate L_n^k(4*r^2) - the generalized Laguerre polynomial
    double laguerre_value = laguerre(n, k, 4.0 * r * r);

    return sign_factor * factorial_ratio * exp_factor * r_factor * laguerre_value;
}

